mapper.update:
UPDATE product_order
SET state      = 'PAID',
    update_time = NOW()
WHERE product_order_id = #{orderId}
  AND buyer_id = #{buyerId}
  AND state = 'PENDING_PAYMENT'

UPDATE product_order
SET state      = 'DELIVERED',
    update_time = NOW()
WHERE product_order_id = #{orderId}
  AND seller_id = #{sellerId}
  AND state = 'PAID'

UPDATE product_order
SET state      = 'COMPLETED',
    update_time = NOW()
WHERE product_order_id = #{orderId}
  AND buyer_id = #{buyerId}
  AND state = 'DELIVERED'

UPDATE product_order
SET state      = 'CANCELLED',
    update_time = NOW()
WHERE product_order_id = #{orderId}
  AND buyer_id = #{buyerId}
  AND state IN ('PENDING_PAYMENT', 'PAID')

