SELECT 
FROM product_order
WHERE buyer_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM product_order
WHERE buyer_id = #{userId}

SELECT 
FROM product_order
WHERE seller_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM product_order
WHERE seller_id = #{userId}
